newBlocks.ez80AssemblyTemplate:
ld a, {SlotID}
call _GetEntityAddressPointer
ld (hl), {InitialXByte}
inc hl
ld (hl), {InitialYByte}

ld a, {SlotID}
ld hl, {XCoordinate}
ld de, {YCoordinate}
call _SetSpritePosition

ld a, {SlotID}
ld b, {VXDelta}
ld c, {VYDelta}
call _SetSpriteVelocity

ld a, {KindAlpha_INDEX}
ld b, {KindBeta_INDEX}
call _CheckSpritesOverlapOfKind
jr nz, _OverlapConditionFailed

ld a, {TopOffset}
ld b, {BottomOffset}
ld c, {LeftOffset}
ld d, {RightOffset}
call _ConfigureSubFullBoundaryHitbox
